use std :: path :: { Path , PathBuf } ; use std :: time :: SystemTime ; use anyhow :: { Context , Result } ; use crate :: cli :: LogsArgs ; # [doc = " Lists all log files in `log_dir`, newest first, one path per line on stdout."] async fn list (log_dir : & Path) -> Result < () > { let mut files = collect_files (log_dir) . await ? ; files . sort_unstable_by_key (| (mtime , _) | * mtime) ; for (_ , path) in files . iter () . rev () { println ! ("{}" , path . display ()) ; } Ok (()) }